package cl.nexbyte.siger.institucional.notificaciones;
import cl.nexbyte.siger.institucional.nucleo.NucleoInstitucional;import cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador;import cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.Resultado;import cl.nexbyte.siger.institucional.robustez.*;
import java.time.*;import java.util.*;import java.security.*;import tools.jackson.databind.json.JsonMapper;
/** Agenda personal y del equipo de Caso. El cumplimiento es manual y no produce actuaciones. */
public final class TareasPersonales {
 private final NucleoInstitucional core;private final BaseJdbc db;private final RecursosNotificacion permisos;private final JsonMapper json;private final Clock clock;
 public TareasPersonales(BaseJdbc db,RecursosNotificacion permisos,JsonMapper json,Clock clock){this.db=db;this.core=permisos.nucleo();this.permisos=permisos;this.json=json;this.clock=clock;}
 public record Edicion(long revision,String titulo,String descripcion,Instant recordatorio,Instant ventanaDesde,Instant ventanaHasta,Instant plazo,String prioridad,String tipoRecurso,UUID recurso,String responsable,Boolean obligatoria,String fundamento){public Edicion(long revision,String titulo,String descripcion,Instant recordatorio,Instant ventanaDesde,Instant ventanaHasta,Instant plazo,String prioridad,String tipoRecurso,UUID recurso,String responsable){this(revision,titulo,descripcion,recordatorio,ventanaDesde,ventanaHasta,plazo,prioridad,tipoRecurso,recurso,responsable,null,null);}@Override public String toString(){return "Edicion[datos privados]";}}
 public record Cambio(long revision,String estado,boolean confirmacionManual,String fundamento){public Cambio(long revision,String estado,boolean confirmacionManual){this(revision,estado,confirmacionManual,null);}}
 public record Tarea(UUID id,String titulo,String descripcion,String creador,String responsable,Instant creada,Instant recordatorio,Instant ventanaDesde,Instant ventanaHasta,Instant plazo,String prioridad,String estado,long revision,String tipoRecurso,UUID recurso,Instant completada,String completadaPor,boolean confirmacionManual,boolean obligatoria,String asignadaPor){@Override public String toString(){return "Tarea[datos privados]";}}
 public record Historia(long secuencia,String autor,Instant fecha,long revision,String evento,Tarea datos,String fundamento){}
 private static Instant fecha(Map<String,Object> r,String k){return r.get(k)==null?null:Instant.ofEpochMilli(((Number)r.get(k)).longValue());}
 private static Long ms(Instant v){return v==null?null:v.toEpochMilli();}
 private Tarea vista(Map<String,Object> r){return new Tarea(UUID.fromString(r.get("id").toString()),r.get("title").toString(),r.get("description_text").toString(),r.get("creator_id").toString(),r.get("responsible_id").toString(),fecha(r,"created_ms"),fecha(r,"reminder_ms"),fecha(r,"execution_from_ms"),fecha(r,"execution_until_ms"),fecha(r,"deadline_ms"),r.get("priority_code").toString(),r.get("state").toString(),((Number)r.get("revision")).longValue(),RecursosNotificacion.contextoTarea(r),RecursosNotificacion.recursoTarea(r),fecha(r,"completed_ms"),(String)r.get("completed_by"),Boolean.TRUE.equals(r.get("manual_confirmed")),Boolean.TRUE.equals(r.get("mandatory")),(String)r.get("assigned_by"));}
 private void validar(Operador a,Edicion e){if(e==null||e.fundamento()!=null&&e.fundamento().length()>2000||e.titulo()==null||e.titulo().isBlank()||e.titulo().length()>180||e.descripcion()!=null&&e.descripcion().length()>6000||e.titulo().chars().anyMatch(Character::isISOControl)||e.prioridad()!=null&&!Set.of("BAJA","NORMAL","ALTA").contains(e.prioridad()))throw new FalloTecnico(400);
  if(e.responsable()!=null&&!a.id().equals(e.responsable())&&!"CASO".equals(e.tipoRecurso()))throw new FalloTecnico(403,"TAREA_PERSONAL");
  if(e.ventanaHasta()!=null&&(e.ventanaDesde()==null||!e.ventanaHasta().isAfter(e.ventanaDesde())))throw new FalloTecnico(400);
  for(var date:Arrays.asList(e.recordatorio(),e.ventanaDesde(),e.ventanaHasta(),e.plazo()))if(date!=null&&(date.isBefore(Instant.parse("2000-01-01T00:00:00Z"))||date.isAfter(Instant.parse("2100-01-01T00:00:00Z"))))throw new FalloTecnico(400);
  if(e.tipoRecurso()!=null&&!Set.of("CASO","SOLICITUD").contains(e.tipoRecurso()))throw new FalloTecnico(400);
  permisos.recurso(a,e.tipoRecurso(),e.recurso());if(!"CASO".equals(e.tipoRecurso())&&Boolean.TRUE.equals(e.obligatoria()))throw new FalloTecnico(400,"OBLIGATORIA_REQUIERE_CASO");
 }
 private void lock(Operador a,String kind,UUID resource){db.sql.queryForObject("SELECT id FROM identity_guard WHERE id=1 FOR UPDATE",Integer.class);permisos.actor(a);if("CASO".equals(kind))core.equipo().bloquear(a,resource);}
 private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(value)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException();}}
 private Resultado anterior(Operador a,UUID key,String op,String digest){if(key==null)throw new FalloTecnico(400);var rows=db.sql.queryForList("SELECT * FROM task_command WHERE id=?",key.toString());if(rows.isEmpty())return null;var r=rows.getFirst();if(!a.id().equals(r.get("actor_id"))||!op.equals(r.get("action_code"))||!digest.equals(r.get("request_hash")))throw new FalloTecnico(409);var id=UUID.fromString(r.get("task_id").toString());leer(a,id);return new Resultado(id,((Number)r.get("result_revision")).longValue());}
 private Resultado comando(Operador a,UUID key,String op,String digest,UUID id,long revision){db.sql.update("INSERT INTO task_command VALUES(?,?,?,?,?,?)",key.toString(),a.id(),op,digest,id.toString(),revision);return new Resultado(id,revision);}
 private void historia(Operador a,UUID id,String code){historia(a,id,code,null);}
 private void historia(Operador a,UUID id,String code,String reason){var t=leer(a,id);db.sql.update("INSERT INTO task_history(task_id,actor_id,at_ms,revision,event_code,snapshot_doc,reason_text) VALUES(?,?,?,?,?,?,?)",id.toString(),a.id(),clock.millis(),t.revision(),code,json.writeValueAsString(t),reason);evento(id,t.revision(),code);}
 private void eventoTemporal(UUID id,long planned,String code){long generation=db.sql.queryForObject("SELECT reminder_generation FROM institution_task WHERE id=?",Long.class,id.toString());String key=id+":"+code+":"+planned+(generation==0?"":":G"+generation);if(db.sql.queryForObject("SELECT COUNT(*) FROM workflow_event WHERE event_key=?",Integer.class,key)==0)db.sql.update("INSERT INTO workflow_event(event_key,code,resource_type,resource_id,at_ms) VALUES(?,? ,'TAREA',?,?)",key,code,id.toString(),clock.millis());}
 private void evento(UUID id,long revision,String code){String key=id+":"+revision+":"+code;if(db.sql.queryForObject("SELECT COUNT(*) FROM workflow_event WHERE event_key=?",Integer.class,key)==0)db.sql.update("INSERT INTO workflow_event(event_key,code,resource_type,resource_id,at_ms) VALUES(?,?,'TAREA',?,?)",key,code,id.toString(),clock.millis());}
 public Resultado crear(Operador a,UUID key,Edicion e){permisos.actor(a);validar(a,e);var digest=hash(e);return db.transaction(()->{lock(a,e.tipoRecurso(),e.recurso());var prev=anterior(a,key,"CREAR",digest);if(prev!=null)return prev;validar(a,e);if("CASO".equals(e.tipoRecurso()))core.equipo().autorizarEjecutor(e.recurso(),e.responsable()==null?a.id():e.responsable());if("CASO".equals(e.tipoRecurso())&&permisos.caso(a,e.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CASO_CERRADO");var id=UUID.randomUUID();db.sql.update("INSERT INTO institution_task(id,creator_id,responsible_id,title,description_text,created_ms,reminder_ms,execution_from_ms,execution_until_ms,deadline_ms,priority_code,state,revision,resource_type,resource_id,request_id,manual_confirmed,mandatory,assigned_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,'PENDIENTE',0,?,?,?,FALSE,?,?)",id.toString(),a.id(),e.responsable()==null?a.id():e.responsable(),e.titulo(),Objects.toString(e.descripcion(),""),clock.millis(),ms(e.recordatorio()),ms(e.ventanaDesde()),ms(e.ventanaHasta()),ms(e.plazo()),e.prioridad()==null?"NORMAL":e.prioridad(),"CASO".equals(e.tipoRecurso())?"CASO":null,"CASO".equals(e.tipoRecurso())?e.recurso().toString():null,"SOLICITUD".equals(e.tipoRecurso())?e.recurso().toString():null,Boolean.TRUE.equals(e.obligatoria()),a.id());historia(a,id,"TAREA_CREADA");caseChanged(a,e.tipoRecurso(),e.recurso(),"AGENDA_TAREA_CREADA");return comando(a,key,"CREAR",digest,id,0);});}
 public Tarea leer(Operador a,UUID id){if(id==null)throw new FalloTecnico(400);var r=permisos.fila("institution_task",id.toString());permisos.tarea(a,r);return vista(r);}
 public List<Tarea> listar(Operador a,String estado){permisos.actor(a);if(estado!=null&&!estado.isBlank()&&!Set.of("PENDIENTE","EN_CURSO","COMPLETADA","CANCELADA").contains(estado))throw new FalloTecnico(400);var rows=db.sql.queryForList("SELECT * FROM institution_task WHERE (creator_id=? OR responsible_id=?)"+(estado==null||estado.isBlank()?"":" AND state=?")+" ORDER BY created_ms DESC,id LIMIT 500",estado==null||estado.isBlank()?new Object[]{a.id(),a.id()}:new Object[]{a.id(),a.id(),estado});var items=new ArrayList<Tarea>();for(var r:rows)try{permisos.tarea(a,r);items.add(vista(r));}catch(FalloTecnico denied){if(!Set.of(401,403,404).contains(denied.status))throw denied;}return items;}
 public Resultado editar(Operador a,UUID key,UUID id,Edicion e){permisos.actor(a);validar(a,e);var digest=hash(List.of(id,e));return db.transaction(()->{lock(a,e.tipoRecurso(),e.recurso());var prev=anterior(a,key,"EDITAR",digest);if(prev!=null)return prev;var t=leer(a,id);if(t.revision()!=e.revision())throw new FalloTecnico(409,"VERSION_OBSOLETA");if(Set.of("COMPLETADA","CANCELADA").contains(t.estado()))throw new FalloTecnico(409);validar(a,e);if(!Objects.equals(t.tipoRecurso(),e.tipoRecurso())||!Objects.equals(t.recurso(),e.recurso()))throw new FalloTecnico(409,"CONTEXTO_TAREA_NO_EDITABLE");String responsible=e.responsable()==null?t.responsable():e.responsable();if("CASO".equals(e.tipoRecurso())&&e.responsable()!=null)core.equipo().autorizarEjecutor(e.recurso(),responsible);boolean assignment=!responsible.equals(t.responsable());boolean mandatory=e.obligatoria()==null?t.obligatoria():e.obligatoria();if(mandatory!=t.obligatoria()&&!a.id().equals(t.creador())&&!a.id().equals(t.asignadaPor())&&!assignment)throw new FalloTecnico(403,"OBLIGATORIEDAD_REQUIERE_ASIGNADOR");if((assignment||mandatory!=t.obligatoria())&&(e.fundamento()==null||e.fundamento().isBlank()))throw new FalloTecnico(400,"FUNDAMENTO_REQUERIDO");if("CASO".equals(t.tipoRecurso())&&mandatory&&core.contextoCaso(a,t.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CASO_CERRADO");db.sql.update("UPDATE institution_task SET title=?,description_text=?,reminder_ms=?,execution_from_ms=?,execution_until_ms=?,deadline_ms=?,priority_code=?,mandatory=?,responsible_id=?,assigned_by=?,reminder_generation=reminder_generation+?,revision=revision+1 WHERE id=?",e.titulo(),Objects.toString(e.descripcion(),""),ms(e.recordatorio()),ms(e.ventanaDesde()),ms(e.ventanaHasta()),ms(e.plazo()),e.prioridad()==null?t.prioridad():e.prioridad(),mandatory,responsible,assignment?a.id():t.asignadaPor(),assignment?1:0,id.toString());historia(a,id,"TAREA_MODIFICADA",e.fundamento());caseChanged(a,t.tipoRecurso(),t.recurso(),"AGENDA_TAREA_MODIFICADA");return comando(a,key,"EDITAR",digest,id,t.revision()+1);});}
 public Resultado estado(Operador a,UUID key,UUID id,Cambio e){permisos.actor(a);if(e==null||e.fundamento()!=null&&e.fundamento().length()>2000||!Set.of("PENDIENTE","EN_CURSO","COMPLETADA","CANCELADA").contains(Objects.toString(e.estado(),""))||e.estado().equals("COMPLETADA")!=e.confirmacionManual())throw new FalloTecnico(400);var digest=hash(List.of(id,e));return db.transaction(()->{var initial=permisos.fila("institution_task",id.toString());lock(a,RecursosNotificacion.contextoTarea(initial),RecursosNotificacion.recursoTarea(initial));var prev=anterior(a,key,"ESTADO",digest);if(prev!=null)return prev;var t=leer(a,id);if(t.revision()!=e.revision())throw new FalloTecnico(409,"VERSION_OBSOLETA");if(Set.of("COMPLETADA","CANCELADA").contains(t.estado())||t.estado().equals(e.estado()))throw new FalloTecnico(409);if(Set.of("PENDIENTE","EN_CURSO").contains(e.estado())&&"CASO".equals(t.tipoRecurso())&&permisos.caso(a,t.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CASO_CERRADO");boolean done=e.estado().equals("COMPLETADA");if(done&&!a.id().equals(t.responsable()))throw new FalloTecnico(403,"CUMPLIMIENTO_SOLO_EJECUTOR");if(e.estado().equals("CANCELADA")&&t.obligatoria()&&(e.fundamento()==null||e.fundamento().isBlank()))throw new FalloTecnico(400,"FUNDAMENTO_REQUERIDO");db.sql.update("UPDATE institution_task SET state=?,revision=revision+1,completed_ms=?,completed_by=?,manual_confirmed=? WHERE id=?",e.estado(),done?clock.millis():null,done?a.id():null,done,id.toString());historia(a,id,done?"TAREA_COMPLETADA":"TAREA_ESTADO_MODIFICADO",e.fundamento());caseChanged(a,t.tipoRecurso(),t.recurso(),"AGENDA_TAREA_ESTADO");return comando(a,key,"ESTADO",digest,id,t.revision()+1);});}
 private Tarea datosHistoricos(Operador a,String doc){var t=json.readValue(doc,Tarea.class);try{permisos.recurso(a,t.tipoRecurso(),t.recurso());return t;}catch(FalloTecnico denied){if(Set.of(403,404).contains(denied.status))return null;throw denied;}}
 public List<Historia> historial(Operador a,UUID id){leer(a,id);return db.sql.queryForList("SELECT * FROM task_history WHERE task_id=? ORDER BY seq DESC LIMIT 100",id.toString()).stream().map(r->new Historia(((Number)r.get("seq")).longValue(),r.get("actor_id").toString(),fecha(r,"at_ms"),((Number)r.get("revision")).longValue(),r.get("event_code").toString(),datosHistoricos(a,r.get("snapshot_doc").toString()),(String)r.get("reason_text"))).toList();}
 private void caseChanged(Operador a,String kind,UUID caso,String code){if("CASO".equals(kind))core.equipo().tareaCambiada(a,caso,code);}
 public record Intento(long revision,String observacion){}
 public Resultado intento(Operador a,UUID key,UUID id,Intento r){if(r==null||r.observacion()==null||r.observacion().isBlank()||r.observacion().length()>2000)throw new FalloTecnico(400);var digest=hash(List.of(id,r));return db.transaction(()->{var raw=permisos.fila("institution_task",id.toString());lock(a,RecursosNotificacion.contextoTarea(raw),RecursosNotificacion.recursoTarea(raw));var previous=anterior(a,key,"INTENTO",digest);if(previous!=null)return previous;var t=leer(a,id);if(!"CASO".equals(t.tipoRecurso())||Set.of("COMPLETADA","CANCELADA").contains(t.estado()))throw new FalloTecnico(409);if(core.contextoCaso(a,t.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CASO_CERRADO");if(t.revision()!=r.revision())throw new FalloTecnico(409,"VERSION_OBSOLETA");db.sql.update("INSERT INTO institution_task_attempt VALUES(?,?,?,?,?,?)",UUID.randomUUID().toString(),id.toString(),a.id(),clock.millis(),r.revision()+1,r.observacion());db.sql.update("UPDATE institution_task SET revision=revision+1 WHERE id=?",id.toString());historia(a,id,"TAREA_INTENTO_CONTACTO");caseChanged(a,t.tipoRecurso(),t.recurso(),"AGENDA_INTENTO_CONTACTO");return comando(a,key,"INTENTO",digest,id,r.revision()+1);});}
 public List<Map<String,Object>> intentos(Operador a,UUID id){leer(a,id);return db.sql.queryForList("SELECT id,actor_id,at_ms,revision,body_text FROM institution_task_attempt WHERE task_id=? ORDER BY at_ms,id",id.toString()).stream().map(r->{Map<String,Object> m=new LinkedHashMap<>();r.forEach((k,v)->m.put(k.toLowerCase(Locale.ROOT),v));return m;}).toList();}
 public List<Tarea> delCaso(Operador a,UUID caso){return db.transaction(()->{core.bloquearAcceso(a);core.autorizarCaso(a,caso);return db.sql.queryForList("SELECT * FROM institution_task WHERE resource_type='CASO' AND resource_id=? ORDER BY created_ms,id",caso.toString()).stream().map(this::vista).toList();});}
 public void transferir(Operador a,UUID caso,String responsable,String anterior,String code){if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Traspaso exige transacción del Caso");core.equipo().autorizarEjecutor(caso,responsable);var pending=db.sql.queryForList("SELECT * FROM institution_task WHERE resource_type='CASO' AND resource_id=? AND state NOT IN ('COMPLETADA','CANCELADA')"+(anterior==null?"":" AND responsible_id=?"),anterior==null?new Object[]{caso.toString()}:new Object[]{caso.toString(),anterior});for(var t:pending){String old=t.get("responsible_id").toString();if(old.equals(responsable))continue;var id=UUID.fromString(t.get("id").toString());db.sql.update("UPDATE institution_task SET responsible_id=?,assigned_by=?,reminder_generation=reminder_generation+1,revision=revision+1 WHERE id=?",responsable,a.id(),id.toString());historia(a,id,code);}}

 public void temporales(){db.transaction(()->{db.sql.queryForObject("SELECT id FROM notification_guard WHERE id=1 FOR UPDATE",Integer.class);var rows=db.sql.queryForList("SELECT id,revision,reminder_ms,deadline_ms,reminder_generation FROM institution_task t WHERE state IN ('PENDIENTE','EN_CURSO') AND ((reminder_ms IS NOT NULL AND reminder_ms<=? AND NOT EXISTS(SELECT 1 FROM workflow_event e WHERE e.event_key=CONCAT(t.id,':TAREA_RECORDATORIO:',t.reminder_ms,CASE WHEN t.reminder_generation=0 THEN '' ELSE CONCAT(':G',t.reminder_generation) END))) OR (deadline_ms IS NOT NULL AND deadline_ms<=? AND NOT EXISTS(SELECT 1 FROM workflow_event e WHERE e.event_key=CONCAT(t.id,':TAREA_VENCIDA:',t.deadline_ms,CASE WHEN t.reminder_generation=0 THEN '' ELSE CONCAT(':G',t.reminder_generation) END)))) ORDER BY created_ms,id LIMIT 20",clock.millis(),clock.millis());for(var r:rows){var id=UUID.fromString(r.get("id").toString());long rev=((Number)r.get("revision")).longValue();if(r.get("reminder_ms")!=null&&((Number)r.get("reminder_ms")).longValue()<=clock.millis())eventoTemporal(id,((Number)r.get("reminder_ms")).longValue(),"TAREA_RECORDATORIO");if(r.get("deadline_ms")!=null&&((Number)r.get("deadline_ms")).longValue()<=clock.millis())eventoTemporal(id,((Number)r.get("deadline_ms")).longValue(),"TAREA_VENCIDA");}return null;});}
}
